html:
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{%- set party = frappe.db.get_value("Customer", doc.customer, ["national_id", "legal_id", "economic_code"], as_dict=True) or {} -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value or 0) | iran_digits }}{%- endmacro -%}
<style>
	.iran-invoice { direction: rtl; text-align: right; font-family: Vazirmatn, Tahoma, "Noto Naskh Arabic", "DejaVu Sans", sans-serif; font-size: 11px; color: #111; }
	.iran-invoice table { width: 100%; border-collapse: collapse; }
	.iran-invoice th, .iran-invoice td { border: 1px solid #444; padding: 4px 6px; vertical-align: top; }
	.iran-invoice th { background: #eee; text-align: center; font-weight: bold; }
	.iran-invoice .head td { border: none; padding: 0 0 8px; }
	.iran-invoice .title { text-align: center; font-size: 18px; font-weight: bold; }
	.iran-invoice .box { border: 1px solid #444; margin-bottom: 8px; }
	.iran-invoice .box h4 { margin: 0; padding: 3px 6px; background: #eee; border-bottom: 1px solid #444; font-size: 12px; }
	.iran-invoice .box .row { padding: 5px 6px; }
	.iran-invoice .num { text-align: left; direction: ltr; white-space: nowrap; }
	.iran-invoice .center { text-align: center; }
	.iran-invoice .totals { width: 50%; margin-right: 0; margin-left: auto; }
	.iran-invoice .sign td { height: 70px; text-align: center; }
	.iran-invoice .muted { color: #666; }
</style>
<div class="iran-invoice">
	<table class="head">
		<tr>
			<td style="width: 30%">
				{% if doc.status == "Draft" or doc.docstatus == 0 %}<span class="muted">{{ _("Draft") }}</span>{% endif %}
			</td>
			<td class="title">صورت‌حساب فروش کالا و خدمات</td>
			<td style="width: 30%">
				<div>شماره صورت‌حساب: <b dir="ltr">{{ doc.name | iran_digits }}</b></div>
				<div>تاریخ: <b dir="ltr">{{ doc.posting_date | jalali_date | iran_digits }}</b></div>
				{% if doc.due_date %}<div>سررسید: <span dir="ltr">{{ doc.due_date | jalali_date | iran_digits }}</span></div>{% endif %}
			</td>
		</tr>
	</table>

	<div class="box">
		<h4>مشخصات فروشنده</h4>
		<div class="row">
			نام شخص حقیقی / حقوقی: <b>{{ doc.company }}</b>
			{% if company.tax_id %} &nbsp;|&nbsp; شماره اقتصادی: {{ company.tax_id | iran_digits }}{% endif %}
			{% if company.phone_no %} &nbsp;|&nbsp; تلفن: {{ company.phone_no | iran_digits }}{% endif %}
			{% if doc.company_address_display %}<div>نشانی: {{ doc.company_address_display }}</div>{% endif %}
		</div>
	</div>

	<div class="box">
		<h4>مشخصات خریدار</h4>
		<div class="row">
			نام شخص حقیقی / حقوقی: <b>{{ doc.customer_name }}</b>
			{% if party.economic_code %} &nbsp;|&nbsp; شماره اقتصادی: <span dir="ltr">{{ party.economic_code | iran_digits }}</span>{% endif %}
			{% if party.national_id %} &nbsp;|&nbsp; کد ملی: <span dir="ltr">{{ party.national_id | iran_digits }}</span>{% endif %}
			{% if party.legal_id %} &nbsp;|&nbsp; شناسه ملی: <span dir="ltr">{{ party.legal_id | iran_digits }}</span>{% endif %}
			{% if doc.contact_mobile %} &nbsp;|&nbsp; تلفن: {{ doc.contact_mobile | iran_digits }}{% endif %}
			{% if doc.address_display %}<div>نشانی: {{ doc.address_display }}</div>{% endif %}
		</div>
	</div>

	<table>
		<thead>
			<tr>
				<th style="width: 4%">ردیف</th>
				<th>شرح کالا یا خدمات</th>
				<th style="width: 8%">تعداد</th>
				<th style="width: 8%">واحد</th>
				<th style="width: 13%">مبلغ واحد</th>
				<th style="width: 13%">تخفیف</th>
				<th style="width: 15%">مبلغ کل پس از تخفیف</th>
			</tr>
		</thead>
		<tbody>
			{% for row in doc.items %}
			<tr>
				<td class="center">{{ loop.index | iran_digits }}</td>
				<td>{{ row.item_name }}{% if row.description and row.description != row.item_name %}<div class="muted">{{ row.description }}</div>{% endif %}</td>
				<td class="center">{{ row.get_formatted("qty", doc) | iran_digits }}</td>
				<td class="center">{{ row.uom }}</td>
				<td class="num">{{ money(row.rate) }}</td>
				<td class="num">{{ money(row.discount_amount * row.qty if row.discount_amount else 0) }}</td>
				<td class="num">{{ money(row.amount) }}</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>

	<table class="totals" style="margin-top: 8px">
		<tr><td>جمع کل</td><td class="num">{{ money(doc.net_total) }}</td></tr>
		{% if doc.discount_amount %}<tr><td>تخفیف کل</td><td class="num">{{ money(doc.discount_amount) }}</td></tr>{% endif %}
		{% for tax in doc.taxes %}
		<tr><td>{{ "مالیات بر ارزش افزوده" if tax.description == "VAT" else (tax.description or tax.account_head) }}{% if tax.rate %} ({{ tax.rate | iran_digits }}٪){% endif %}</td><td class="num">{{ money(tax.tax_amount) }}</td></tr>
		{% endfor %}
		<tr><th>مبلغ قابل پرداخت ({{ doc.currency }})</th><th class="num">{{ money(doc.rounded_total or doc.grand_total) }}</th></tr>
	</table>

	{% if doc.terms or doc.remarks %}
	<div class="box" style="margin-top: 8px"><h4>توضیحات</h4><div class="row">{{ doc.terms or doc.remarks }}</div></div>
	{% endif %}

	<table class="sign" style="margin-top: 14px">
		<tr><td>مهر و امضای فروشنده</td><td>مهر و امضای خریدار</td></tr>
	</table>
</div>
